WITH exploded AS (SELECT id, plan, currency, EXPLODE(tier_limits) AS tier_value FROM price_tiers) SELECT CASE WHEN tier_value >= 61 THEN 'LARGE' ELSE 'SMALL' END AS tier_value_tier, currency, COUNT(DISTINCT plan) AS distinct_plans, ROUND(SUM(tier_value) / NULLIF(COUNT(CASE WHEN plan = 'basic' THEN 1 END), 0), 2) AS tier_value_per_basic, APPROX_PERCENTILE(tier_value, 0.5) AS tier_value_p50, RANK() OVER (PARTITION BY CASE WHEN tier_value >= 61 THEN 'LARGE' ELSE 'SMALL' END ORDER BY COUNT(DISTINCT plan) DESC) AS distinct_plans_rank FROM exploded GROUP BY 1, 2 ORDER BY tier_value_tier DESC;
